SELECT '01M63VC638J5R2BZ101DNTJE6W', 'otc-vs-prescription-hearing-aids', 'published', '2026-09-26T16:03:00.000Z', '2026-09-26T16:03:00.000Z', '2026-09-26T16:03:00.000Z', 1, 'en', 'OTC vs Prescription Hearing Aids: Which Fits Your Hearing Loss?', 'OTC vs Prescription Hearing Aids | New Leaf Hearing Care', 'OTC hearing aids suit mild to moderate loss in adults. Prescription aids are programmed to your test. Explore hearing aids in Arvada and Littleton, CO.',
  'New Leaf Hearing Care', 'September 26, 2026', 'Hearing Aids', '{"mediaId": "01M63VC6380CT1BQNXCSBMRHV0", "provider": "local", "storageKey": "otc-vs-prescription-hearing-aids.webp", "meta": {"storageKey": "otc-vs-prescription-hearing-aids.webp", "width": 980, "height": 551, "filename": "otc-vs-prescription-hearing-aids.webp"}, "alt": "Caregiver placing a behind-the-ear hearing aid on an older man", "width": 980, "height": 551, "url": "/_emdash/api/media/file/otc-vs-prescription-hearing-aids.webp"}', '[{"_type":"block","_key":"otcb1","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs1_0","text":"Over-the-counter (OTC) hearing aids are for adults with mild to moderate hearing loss who want to set up the devices themselves. Prescription hearing aids are programmed by an audiologist from your hearing test, and can be fitted for any level of loss.","marks":[]}]},{"_type":"block","_key":"otcb2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs2_0","text":"We fit prescription hearing aids at our offices in Arvada and Littleton.","marks":[]}]},{"_type":"block","_key":"otcb3","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"otcs3_0","text":"Can I buy hearing aids without a doctor’s visit?","marks":[]}]},{"_type":"block","_key":"otcb4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs4_0","text":"Yes, if you are 18 or older and believe you have mild to moderate hearing loss. Since October 17, 2022, you can buy OTC hearing aids in a store or online with no prescription and no visit to an audiologist or doctor.","marks":[]}]},{"_type":"block","_key":"otcb5","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs5_0","text":"The FDA wrote that rule for adults with perceived mild to moderate loss. Severe and profound loss falls outside it, and so does anyone under 18. Those hearing aids remain prescription devices.","marks":[]}]},{"_type":"block","_key":"otcb6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs6_0","text":"The FDA says ‘perceived’ because OTC buyers decide for themselves that their loss is mild to moderate.","marks":[]}]},{"_type":"block","_key":"otcb7","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs7_0","text":"The FDA requires every OTC hearing aid box to carry a “red flag” warning. It says to see a doctor, preferably an ear, nose, and throat (ENT) doctor, if any of these apply:","marks":[]}]},{"_type":"block","_key":"otcb8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs8_0","text":"Your ear has a birth defect or an unusual shape, or it was injured in an accident.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"otcb9","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs9_0","text":"Blood, pus, or fluid has come out of your ear in the past 6 months.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"otcb10","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs10_0","text":"Your ear feels painful or uncomfortable.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"otcb11","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs11_0","text":"You have a lot of ear wax, or you think something is in your ear.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"otcb12","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs12_0","text":"You get really dizzy or have a spinning or swaying feeling.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"otcb13","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs13_0","text":"Your hearing changed suddenly in the past 6 months, or it gets worse and then better again.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"otcb14","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs14_0","text":"Your hearing is worse in one ear, or you hear ringing or buzzing in only one ear.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"otcb15","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"otcs15_0","text":"How to tell if your loss is mild to moderate","marks":[]}]},{"_type":"block","_key":"otcb16","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs16_0","text":"You find out with a hearing test. At New Leaf Hearing Care, we play tones at different pitches, and you tell us when you hear them, one ear at a time. Then we check how well you understand spoken words. The results show whether your loss falls in the mild to moderate range the FDA covers.","marks":[]}]},{"_type":"block","_key":"otcb17","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs17_0","text":"Our guidance is a baseline hearing test at age 40, earlier if you notice a problem. After 50, we test every one to two years. Once a loss is diagnosed, we test every year.","marks":[]}]},{"_type":"block","_key":"otcb18","style":"normal","markDefs":[{"_key":"otcl18_1","_type":"link","href":"https://newleafhearing.com/audiology-services/hearing-assessments/"}],"children":[{"_type":"span","_key":"otcs18_0","text":"Book a ","marks":[]},{"_type":"span","_key":"otcs18_1","text":"hearing test in Arvada or Littleton","marks":["otcl18_1"]},{"_type":"span","_key":"otcs18_2","text":".","marks":[]}]},{"_type":"block","_key":"otcb19","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"otcs19_0","text":"What a prescription fitting adds","marks":[]}]},{"_type":"block","_key":"otcb20","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs20_0","text":"An audiologist programs the hearing aid to your test results, measures the sound inside your ear, and adjusts it after you have worn it. An OTC purchase at a store or online does not include those steps.","marks":[]}]},{"_type":"block","_key":"otcb21","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs21_0","text":"We set the volume pitch by pitch, because hearing loss rarely hits every pitch equally. A thin probe microphone then sits in your ear canal while the hearing aid plays, so we read what reaches your eardrum and correct it. A setting that looks right on a screen can sound different in your ear, which is why we measure it.","marks":[]}]},{"_type":"block","_key":"otcb22","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs22_0","text":"Louder is not always clearer. Once you have worn the hearing aids in real places, you tell us what sounded off and we adjust.","marks":[]}]},{"_type":"block","_key":"otcb23","style":"normal","markDefs":[{"_key":"otcl23_1","_type":"link","href":"https://newleafhearing.com/hearing-aids-products/hearing-aid-fittings/"}],"children":[{"_type":"span","_key":"otcs23_0","text":"We provide professional ","marks":[]},{"_type":"span","_key":"otcs23_1","text":"hearing aid fittings in Arvada and Littleton","marks":["otcl23_1"]},{"_type":"span","_key":"otcs23_2","text":".","marks":[]}]},{"_type":"block","_key":"otcb24","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"otcs24_0","text":"Are OTC hearing aids cheaper?","marks":[]}]},{"_type":"block","_key":"otcb25","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs25_0","text":"OTC hearing aids cost less at the register. HearingTracker’s September 2026 review of top OTC picks lists prices from about $300 to about $2,000 a pair.","marks":[]}]},{"_type":"block","_key":"otcb26","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs26_0","text":"A prescription pair costs more, and the difference pays for the work around the device. Our audiologists program the hearing aids to your test, check the sound in your ear with a probe microphone, teach you to use and clean them, and see you again to adjust.","marks":[]}]},{"_type":"block","_key":"otcb27","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs27_0","text":"The FDA says it takes time and practice to get used to hearing aids, and it suggests a consultation with a hearing health care professional if an OTC pair isn’t helping.","marks":[]}]},{"_type":"block","_key":"otcb28","style":"normal","markDefs":[{"_key":"otcl28_1","_type":"link","href":"https://newleafhearing.com/hearing-aid-price-calculator/"},{"_key":"otcl28_3","_type":"link","href":"https://newleafhearing.com/resources/insurance/"},{"_key":"otcl28_5","_type":"link","href":"https://newleafhearing.com/resources/financing-options/"}],"children":[{"_type":"span","_key":"otcs28_0","text":"You can run numbers before you book with our ","marks":[]},{"_type":"span","_key":"otcs28_1","text":"pricing estimator","marks":["otcl28_1"]},{"_type":"span","_key":"otcs28_2","text":". Our pages on ","marks":[]},{"_type":"span","_key":"otcs28_3","text":"insurance","marks":["otcl28_3"]},{"_type":"span","_key":"otcs28_4","text":" and ","marks":[]},{"_type":"span","_key":"otcs28_5","text":"financing options","marks":["otcl28_5"]},{"_type":"span","_key":"otcs28_6","text":" explain how to pay for a visit.","marks":[]}]},{"_type":"block","_key":"otcb29","style":"normal","markDefs":[{"_key":"otcl29_1","_type":"link","href":"https://newleafhearing.com/audiology-services/hearing-assessments/"}],"children":[{"_type":"span","_key":"otcs29_0","text":"Book a ","marks":[]},{"_type":"span","_key":"otcs29_1","text":"hearing test in Arvada or Littleton","marks":["otcl29_1"]},{"_type":"span","_key":"otcs29_2","text":" and we will tell you what type fits your loss and what a pair would cost.","marks":[]}]},{"_type":"block","_key":"otcb30","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"otcs30_0","text":"Which is more effective for severe hearing loss?","marks":[]}]},{"_type":"block","_key":"otcb31","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs31_0","text":"Prescription hearing aids are more effective for severe loss. The FDA says OTC hearing aids are intended for perceived mild to moderate loss and not for severe or profound loss.","marks":[]}]},{"_type":"block","_key":"otcb32","style":"normal","markDefs":[{"_key":"otcl32_1","_type":"link","href":"https://newleafhearing.com/oticon-hearing-aids/"},{"_key":"otcl32_3","_type":"link","href":"https://newleafhearing.com/phonak-hearing-aids/"}],"children":[{"_type":"span","_key":"otcs32_0","text":"Severe loss calls for more power and a precise fit. Our ","marks":[]},{"_type":"span","_key":"otcs32_1","text":"Oticon page","marks":["otcl32_1"]},{"_type":"span","_key":"otcs32_2","text":" lists the Xceed, a behind-the-ear model made for severe to profound loss, and our ","marks":[]},{"_type":"span","_key":"otcs32_3","text":"Phonak page","marks":["otcl32_3"]},{"_type":"span","_key":"otcs32_4","text":" lists the Naída Lumity for significant loss. An audiologist picks the model and fits it.","marks":[]}]},{"_type":"block","_key":"otcb33","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"otcs33_0","text":"Hearing aid customization","marks":[]}]},{"_type":"block","_key":"otcb34","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs34_0","text":"Prescription hearing aids offer more customization. You set an OTC hearing aid yourself with its volume control or app. We program a prescription hearing aid to your test, then set features around your days, such as speech help in noisy restaurants and Bluetooth streaming for phone calls.","marks":[]}]},{"_type":"block","_key":"otcb35","style":"normal","markDefs":[{"_key":"otcl35_1","_type":"link","href":"https://newleafhearing.com/hearing-aids-products/hearing-aid-styles/"}],"children":[{"_type":"span","_key":"otcs35_0","text":"Custom earmolds are made from an impression of your ear, and they help reduce feedback. Learn more about different ","marks":[]},{"_type":"span","_key":"otcs35_1","text":"hearing aid styles","marks":["otcl35_1"]},{"_type":"span","_key":"otcs35_2","text":".","marks":[]}]},{"_type":"block","_key":"otcb36","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"otcs36_0","text":"Explore hearing aids in Arvada or Littleton","marks":[]}]},{"_type":"block","_key":"otcb37","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs37_0","text":"New Leaf Hearing Care offers a wide selection of hearing aids in Arvada and Littleton, CO.","marks":[]}]},{"_type":"block","_key":"otcb38","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs38_0","text":"Arvada: 8721 Wadsworth Blvd, Suite C, (303) 639-5323.","marks":[]}]},{"_type":"block","_key":"otcb39","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"otcs39_0","text":"Littleton: 5808 S Rapp St, Suite 102, (720) 689-7989.","marks":[]}]},{"_type":"block","_key":"otcb40","style":"normal","markDefs":[{"_key":"otcl40_1","_type":"link","href":"https://newleafhearing.com/schedule-appointment/"}],"children":[{"_type":"span","_key":"otcs40_0","text":"Call us or ","marks":[]},{"_type":"span","_key":"otcs40_1","text":"schedule an appointment online","marks":["otcl40_1"]},{"_type":"span","_key":"otcs40_2","text":".","marks":[]}]}]'
